import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';

// cases file: JSON array of {name, argv}
const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));

const out = [];
for (const c of cases) {
  const r = spawnSync(EXE, c.argv, { encoding: 'buffer' });
  out.push({
    name: c.name,
    argv: c.argv,
    exitCode: r.status,
    signal: r.signal,
    stdout: r.stdout.toString('utf8'),
    stdoutHex: r.stdout.toString('hex'),
    stdoutLen: r.stdout.length,
    stderr: r.stderr.toString('utf8'),
    stderrLen: r.stderr.length,
  });
}
console.log(JSON.stringify(out, null, 1));

import { writeFileSync } from 'node:fs';

const C = [];
const add = (name, argv) => C.push({ name, argv });

// ---- 1. FIPS-197 style attempts with printable ASCII only ----
// FIPS-197 C.1 key/PT contain NUL and other non-printables => impossible via argv.
// Closest printable analogues:
add('k16-fips-substitute-lowhex', ['--key', '000102030405060708090a0b0c0d0e0f'.slice(0, 16), '--data', '00112233445566778899aabbccddeeff'.slice(0, 16)]);

// ---- 2. Regression suite, key 16 bytes ----
add('k16-d16-a', ['--key', 'aaaaaaaaaaaaaaaa', '--data', '0123456789abcdef']);
add('k16-d32-a', ['--key', '0123456789abcdef', '--data', 'The quick brown fox jumps over t']);
add('k16-d48-sample1', ['--key', '4)9PfvFH4vtYbj #', '--data', 'Fgoy$38USLH;|sEffFv7IVmVvO-=IWE|@6LV<[pA5.8GNQo[']);
add('k16-d64-a', ['--key', 'YELLOW SUBMARINE', '--data', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/']);
add('k16-d16-punct', ['--key', '~!@#$%^&*()_+{}|', '--data', ' !"#$%&\'()*+,-./']);
add('k16-d32-punct2', ['--key', '0123456789:;<=>?', '--data', '@ABCDEFGHIJKLMNO[\\]^_`{|}~ \tXYZ'.slice(0, 32)]);
add('k16-d48-zeros', ['--key', '0000000000000000', '--data', '000000000000000000000000000000000000000000000000']);
add('k16-d64-spaces', ['--key', '                ', '--data', '                                                                ']);

// ---- key 24 bytes ----
add('k24-d16-a', ['--key', 'a'.repeat(24), '--data', '0123456789abcdef']);
add('k24-d32-a', ['--key', 'abcdefghijklmnopqrstuvwx', '--data', 'The quick brown fox jumps over t']);
add('k24-d48-a', ['--key', 'Twenty-four byte key!!!!', '--data', 'Fgoy$38USLH;|sEffFv7IVmVvO-=IWE|@6LV<[pA5.8GNQo[']);
add('k24-d64-a', ['--key', '012345678901234567890123', '--data', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/']);
add('k24-d16-punct', ['--key', '~!@#$%^&*()_+{}|:"<>?,./', '--data', ' !"#$%&\'()*+,-./']);
add('k24-d32-zeros', ['--key', '0'.repeat(24), '--data', '0'.repeat(32)]);

// ---- key 32 bytes ----
add('k32-d16-a', ['--key', 'a'.repeat(32), '--data', '0123456789abcdef']);
add('k32-d32-a', ['--key', 'abcdefghijklmnopqrstuvwxyzABCDEF', '--data', 'The quick brown fox jumps over t']);
add('k32-d48-a', ['--key', 'This is a 32-byte AES-256 key!!!', '--data', 'Fgoy$38USLH;|sEffFv7IVmVvO-=IWE|@6LV<[pA5.8GNQo[']);
add('k32-d64-a', ['--key', '01234567890123456789012345678901', '--data', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/']);
add('k32-d16-punct', ['--key', '~!@#$%^&*()_+{}|:"<>?,./;\'[]\\`-=', '--data', ' !"#$%&\'()*+,-./']);
add('k32-d80-a', ['--key', 'a'.repeat(32), '--data', 'A'.repeat(80)]);

// ---- 3. invalid key sizes ----
for (const n of [0, 1, 15, 17, 23, 25, 31, 33, 48, 64]) {
  add(`keysize-${n}`, ['--key', 'a'.repeat(n), '--data', '0123456789abcdef']);
}

// ---- 4. data lengths ----
for (const n of [0, 1, 15, 16, 17, 31, 32, 33, 47, 48, 64, 80, 96, 160]) {
  add(`datalen-${n}`, ['--key', 'aaaaaaaaaaaaaaaa', '--data', 'x'.repeat(n)]);
}

// ---- 6. ECB determinism ----
add('ecb-det-3same', ['--key', 'aaaaaaaaaaaaaaaa', '--data', 'BLOCKBLOCKBLOCK1'.repeat(3)]);
add('ecb-det-mixed', ['--key', 'aaaaaaaaaaaaaaaa', '--data', 'AAAAAAAAAAAAAAAA' + 'BBBBBBBBBBBBBBBB' + 'AAAAAAAAAAAAAAAA']);

writeFileSync('/tmp/cases1.json', JSON.stringify(C));
console.log('cases:', C.length);
for (const c of C) {
  console.log(c.name, 'keybytes=', Buffer.byteLength(c.argv[1], 'utf8'), 'databytes=', Buffer.byteLength(c.argv[3], 'utf8'));
}

