// Scratch from-scratch AES (ECB, single block) to cross-validate FIPS-197 KAT
// and the reference executable output.

const SBOX = new Uint8Array(256);
const INV = new Uint8Array(256);
(function build() {
  // multiplicative inverse in GF(2^8) via log/exp tables with generator 3
  const exp = new Uint8Array(512), log = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    exp[i] = x; log[x] = i;
    x ^= (x << 1) ^ ((x & 0x80) ? 0x11b : 0);
    x &= 0xff;
  }
  for (let i = 255; i < 512; i++) exp[i] = exp[i - 255];
  for (let i = 0; i < 256; i++) {
    const inv = i === 0 ? 0 : exp[255 - log[i]];
    let s = inv ^ (inv << 1) ^ (inv << 2) ^ (inv << 3) ^ (inv << 4);
    s = (s ^ (s >>> 8) ^ 0x63) & 0xff;
    SBOX[i] = s; INV[s] = i;
  }
})();

const xtime = (a) => ((a << 1) ^ ((a & 0x80) ? 0x1b : 0)) & 0xff;
const mul = (a, b) => { let r = 0; while (b) { if (b & 1) r ^= a; a = xtime(a); b >>>= 1; } return r & 0xff; };

export function expandKey(key) {
  const Nk = key.length / 4;
  if (![4, 6, 8].includes(Nk)) throw new Error('Invalid key size');
  const Nr = Nk + 6;
  const w = [];
  for (let i = 0; i < Nk; i++) w.push([key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]);
  let rcon = 1;
  for (let i = Nk; i < 4 * (Nr + 1); i++) {
    let t = w[i - 1].slice();
    if (i % Nk === 0) {
      t = [SBOX[t[1]] ^ rcon, SBOX[t[2]], SBOX[t[3]], SBOX[t[0]]];
      rcon = xtime(rcon);
    } else if (Nk > 6 && i % Nk === 4) {
      t = t.map((b) => SBOX[b]);
    }
    w.push(t.map((b, j) => b ^ w[i - Nk][j]));
  }
  return { w, Nr };
}

export function encryptBlock(key, block) {
  const { w, Nr } = expandKey(key);
  // state is column-major: s[r][c] = block[r + 4c]
  let s = new Uint8Array(block);
  const addRoundKey = (round) => {
    for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) s[4 * c + r] ^= w[round * 4 + c][r];
  };
  addRoundKey(0);
  for (let round = 1; round <= Nr; round++) {
    for (let i = 0; i < 16; i++) s[i] = SBOX[s[i]];
    // ShiftRows
    const t = new Uint8Array(16);
    for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) t[4 * c + r] = s[4 * ((c + r) % 4) + r];
    s = t;
    if (round !== Nr) {
      for (let c = 0; c < 4; c++) {
        const a0 = s[4 * c], a1 = s[4 * c + 1], a2 = s[4 * c + 2], a3 = s[4 * c + 3];
        s[4 * c] = mul(a0, 2) ^ mul(a1, 3) ^ a2 ^ a3;
        s[4 * c + 1] = a0 ^ mul(a1, 2) ^ mul(a2, 3) ^ a3;
        s[4 * c + 2] = a0 ^ a1 ^ mul(a2, 2) ^ mul(a3, 3);
        s[4 * c + 3] = mul(a0, 3) ^ a1 ^ a2 ^ mul(a3, 2);
      }
    }
    addRoundKey(round);
  }
  return Buffer.from(s);
}

export { SBOX, INV };

