import { readFileSync } from 'node:fs';
import { encryptBlock } from '/tmp/aes.mjs';

export function pyBytesRepr(buf) {
  let q = "'";
  if (buf.includes(0x27) && !buf.includes(0x22)) q = '"';
  let s = 'b' + q;
  for (const c of buf) {
    if (c === q.charCodeAt(0) || c === 0x5c) s += '\\' + String.fromCharCode(c);
    else if (c === 0x09) s += '\\t';
    else if (c === 0x0a) s += '\\n';
    else if (c === 0x0d) s += '\\r';
    else if (c < 0x20 || c >= 0x7f) s += '\\x' + c.toString(16).padStart(2, '0');
    else s += String.fromCharCode(c);
  }
  return s + q;
}

const results = JSON.parse(readFileSync('/tmp/out1.json', 'utf8'));
let pass = 0, fail = 0, skipped = 0;
for (const r of results) {
  if (r.exitCode !== 0) { skipped++; continue; }
  const key = Buffer.from(r.argv[1], 'utf8');
  const data = Buffer.from(r.argv[3], 'utf8');
  if (![16,24,32].includes(key.length) || data.length % 16 !== 0) { skipped++; continue; }
  let expected = '';
  for (let i = 0; i < data.length; i += 16) expected += pyBytesRepr(encryptBlock(key, data.subarray(i, i+16))) + '\n';
  if (expected === r.stdout) { pass++; }
  else { fail++; console.log('MISMATCH ' + r.name + '\n  got:\n' + r.stdout + '  exp:\n' + expected); }
}
console.log(`crosscheck: pass=${pass} fail=${fail} skipped(non-zero-exit)=${skipped}`);
EOF
node /tmp/xcheck.mjs

