import { writeFileSync } from 'node:fs';
const C = [];
const add = (name, key, data) => C.push({ name, argv: ['--key', key, '--data', data] });

const E = 'é';      // e-acute, 2 UTF-8 bytes c3 a9
const EU = '€';     // euro sign, 3 UTF-8 bytes e2 82 ac
const CLEF = '\u{1D11E}';// musical G clef, 4 UTF-8 bytes f0 9d 84 9e

// key byte-length governs validation
add('utf8-key-15chars-16bytes', 'a'.repeat(14) + E, '0123456789abcdef');
add('utf8-key-8chars-16bytes',  E.repeat(8),        '0123456789abcdef');
add('utf8-key-6chars-16bytes',  EU.repeat(5) + 'a', '0123456789abcdef');
add('utf8-key-16chars-17bytes', 'a'.repeat(15) + E, '0123456789abcdef'); // 17 bytes -> ValueError
add('utf8-key-16chars-32bytes', E.repeat(16),       '0123456789abcdef'); // 32 bytes -> AES-256 OK
add('utf8-key-8chars-24bytes',  EU.repeat(8),       '0123456789abcdef');
add('utf8-key-8chars-32bytes',  CLEF.repeat(8),     '0123456789abcdef');
add('utf8-key-4chars-16bytes',  CLEF.repeat(4),     '0123456789abcdef');

// data byte-length governs block splitting
add('utf8-data-8chars-16bytes',  'aaaaaaaaaaaaaaaa', E.repeat(8));
add('utf8-data-16chars-32bytes', 'aaaaaaaaaaaaaaaa', E.repeat(16));
add('utf8-data-12chars-24bytes', 'aaaaaaaaaaaaaaaa', E.repeat(8) + 'abcdefgh'); // 24 bytes -> ValueError
add('utf8-data-split-midchar',   'aaaaaaaaaaaaaaaa', 'a'.repeat(15) + E + 'b'.repeat(15)); // 32 bytes, char straddles boundary
add('utf8-data-6chars-16bytes',  'aaaaaaaaaaaaaaaa', EU.repeat(5) + 'a');
add('utf8-data-4chars-16bytes',  'aaaaaaaaaaaaaaaa', CLEF.repeat(4));
add('utf8-both',                 E.repeat(8),        CLEF.repeat(4) + EU.repeat(5) + 'a');

writeFileSync('/tmp/cases2.json', JSON.stringify(C));
for (const c of C) {
  const k = Buffer.from(c.argv[1], 'utf8'), d = Buffer.from(c.argv[3], 'utf8');
  console.log(c.name.padEnd(26), 'keychars=' + [...c.argv[1]].length, 'keybytes=' + k.length, 'keyhex=' + k.toString('hex'));
  console.log(''.padEnd(26), 'datachars=' + [...c.argv[3]].length, 'databytes=' + d.length, 'datahex=' + d.toString('hex'));
}
EOF
