cat > /tmp/hunt.mjs <<'EOF'
import { encryptBlock } from '/tmp/aes.mjs';
const key = Buffer.from('aaaaaaaaaaaaaaaa');
const base = Buffer.from('0000000000000000');
const alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
let bothQuotes = null, hasBackslash = null, quoteOnly = null, nlOrTab = null;
outer:
for (let i = 0; i < 3000000; i++) {
  const d = Buffer.from(base);
  let n = i;
  for (let p = 0; p < 6; p++) { d[15 - p] = alpha.charCodeAt(n % 62); n = Math.floor(n / 62); }
  const c = encryptBlock(key, d);
  const hasSq = c.includes(0x27), hasDq = c.includes(0x22), hasBs = c.includes(0x5c);
  if (!bothQuotes && hasSq && hasDq) bothQuotes = [d.toString('latin1'), c.toString('hex')];
  if (!quoteOnly && hasSq && !hasDq) quoteOnly = [d.toString('latin1'), c.toString('hex')];
  if (!hasBackslash && hasBs) hasBackslash = [d.toString('latin1'), c.toString('hex')];
  if (!nlOrTab && (c.includes(0x0a) || c.includes(0x09) || c.includes(0x0d))) nlOrTab = [d.toString('latin1'), c.toString('hex')];
  if (bothQuotes && hasBackslash && quoteOnly && nlOrTab) break outer;
}
console.log('bothQuotes  ', JSON.stringify(bothQuotes));
console.log('quoteOnly   ', JSON.stringify(quoteOnly));
console.log('hasBackslash', JSON.stringify(hasBackslash));
console.log('nlOrTab     ', JSON.stringify(nlOrTab));
EOF
